    .select()
    .from(organizationSlugRetirements)
    .where(eq(organizationSlugRetirements.slug, slug))
    .get();
  if (!retired || !isHoldActive(retired.retiredAt, Date.now())) return null;

  const held = getDb()
    .select()
    .from(organizations)
