 * Renames a workspace's slug in one transaction. Returns `null`, changing
 * nothing, when the slug is held by another workspace (current or retired and
 * still within the hold). Otherwise the old slug is retired at `now`, and any
 * retirement the workspace holds on the new slug ends.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  to: string,
  now: IsoTimestamp,
): Promise<Organization | null> {
  return getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) throw new Error(`Organization ${orgId} not found`);

    const holder = tx
      .select({ id: organizations.id })
      .from(organizations)
      .where(eq(organizations.slug, to))
      .get();
    if (holder && holder.id !== orgId) return null;

    const retired = tx
      .select()
      .from(organizationSlugRetirements)
      .where(eq(organizationSlugRetirements.slug, to))
      .get();
    if (
      retired &&
      retired.orgId !== orgId &&
      isHoldActive(retired.retiredAt, Date.parse(now))
    ) {
      return null;
    }

    // Ends this workspace's own retirement of `to`, or clears an expired hold.
    tx.delete(organizationSlugRetirements)
      .where(eq(organizationSlugRetirements.slug, to))
      .run();

    tx.insert(organizationSlugRetirements)
      .values({ slug: current.slug, orgId, retiredAt: now })
      .onConflictDoUpdate({
        target: organizationSlugRetirements.slug,
        set: { orgId, retiredAt: now },
      })
      .run();

    const row = tx
      .update(organizations)
      .set({ slug: to, updatedAt: now })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

