  return parseIso(retiredAt).getTime() + ORG_SLUG_HOLD_DAYS * DAY_MS > now;
}

/**
 * Resolves a slug to a live workspace: its current slug first, then a slug it
 * retired within the hold window. Every slug-to-workspace lookup goes through here.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const retired = getDb()
    .select()
    .from(organizationSlugRetirements)
    .where(eq(organizationSlugRetirements.slug, slug))
    .get();
  if (!retired || !isHoldActive(retired.retiredAt, Date.now())) return null;

  const held = getDb()
    .select()
    .from(organizations)
    .where(
      and(
        eq(organizations.id, retired.orgId),
        isNull(organizations.archivedAt),
      ),
    )
    .get();
  return held ? toOrganization(held) : null;
}
