    .select({
      slug: organizationSlugRetirements.slug,
      retiredAt: organizationSlugRetirements.retiredAt,
    })
    .from(organizationSlugRetirements)
    .where(like(organizationSlugRetirements.slug, `${prefix}%`))
    .all();

